# gas-puff flow command (L1)
flow_cmd = density_mpc(n_e_edge, n_ref).fast
if plenum_P_ok and vac_valve_open and not disruption_lock:
    piezo_valve.set(flow_cmd)               # ms response
else:
    piezo_valve.close()                      # fail-closed

# fast beam notch (L1 protection)
if shinethrough > s_max or duct_T > T_max or disruption_precursor:
    beam_gate.notch()          # blank in us, keep source alive
# resume only when cause clears and supervisor re-arms
if cause_cleared and rearmed:
    beam_gate.restore(power_ref)

# purity gate before fueling delivery (L3/L4)
if d_fraction >= d_min and impurity_ppm <= imp_max:
    plenum.regulate(P_ref)
    allow_fueling(consumer)
else:
    divert_to_cleanup(); block_fueling(consumer)

# blanket thermal + breeding monitor (L3/L4)
for m in modules:
    if m.T > T_limit: derate_local_power_or_flow(m)
# effective breeding estimate from neutronics + purge assay
TBR_eff = breed_measured / neutron_source_est
reconcile(TBR_eff, TBR_design_lever)

# rainflow fatigue accumulation (twin, slow loop)
cycles = rainflow(strain_history[node])
for (amp, mean, n) in cycles:
    D[node] += n / N_allow(amp, mean)     # Miner's rule
if D[node] > D_warn:
    schedule_inspection(node)             # predictive maintenance

# first-wall protection (L1/L3)
q_surf = infer_heatflux(ir_thermography, thermocouples)
if q_surf > q_limit or dT_dt > ramp_limit:
    inject_radiator_gas()        # spread load radiatively (ms)
    derate_beam_power()          # reduce input power
    if q_surf > q_trip: abort_to_safe_state()

# feedthrough interlock (L1)
if vac_leak > leak_max or seal_fault:
    close_all_fueling(); notch_beams()      # fail-safe
if cryo_heatleak > budget:
    raise_magnet_protection_posture()
